#!/usr/bin/env python3
"""Generate the six static, offline tool pages. No user data is read."""
from pathlib import Path
import html
ROOT=Path(__file__).resolve().parent.parent
CSS='''*{box-sizing:border-box}:root{font:16px/1.7 system-ui,-apple-system,"Segoe UI",sans-serif;color:#22342b;background:#f6f7f1}body{margin:0}header,main,footer{max-width:1160px;margin:auto;padding:26px 48px}header{display:flex;justify-content:space-between;align-items:center;border-bottom:1px solid #d4ddcf}.brand{font-size:24px;font-weight:760;text-decoration:none;color:inherit}.brand span{font-weight:400;color:#60715e;font-size:13px;margin-left:14px}nav{display:flex;gap:24px}a{color:#286044;text-underline-offset:4px}nav a{text-decoration:none;font-size:14px}main{padding-top:70px;padding-bottom:84px}.eyebrow{font-size:12px;letter-spacing:2px;color:#536c4e;text-transform:uppercase}h1{font-size:clamp(36px,4.5vw,62px);line-height:1.18;letter-spacing:-2px;max-width:800px;font-weight:700;margin:20px 0 28px}h2{font-size:26px;font-weight:650;margin-top:44px}.lead{font-size:20px;color:#50634e;max-width:720px}.button{display:inline-block;padding:11px 22px;border-radius:6px;background:#2e6041;color:#fff;text-decoration:none;margin:18px 12px 10px 0}.button.alt{color:#2e6041;background:transparent;border:1px solid #acbe9e}.note{font-size:14px;color:#5d7156}.tools{margin-top:58px;border-top:1px solid #bdcdb4}.tool{display:grid;grid-template-columns:65px 1fr 260px;gap:28px;padding:30px 0;border-bottom:1px solid #bdcdb4;align-items:start}.num{font-size:14px;color:#64795a;padding-top:8px}.tool h2{margin:0;font-size:25px}.tool p{margin:8px 0}.tool aside{font-size:14px;color:#5a6e51}.sample{background:#e8eee0;border:1px solid #cad8bf;border-radius:10px;padding:28px;margin:28px 0;max-width:850px}.sample pre{font:15px/1.9 ui-monospace,monospace;white-space:pre-wrap;overflow-wrap:anywhere}.sample small{color:#627455}ol,ul{padding-left:24px;max-width:850px}li{margin:10px 0}.download{padding:22px 0;border-top:1px solid #cad8bf}.download h3{font-size:20px;margin:0 0 8px}.hash{font:12px/1.8 ui-monospace,monospace;overflow-wrap:anywhere}footer{border-top:1px solid #d4ddcf;display:flex;justify-content:space-between;color:#65765a;font-size:13px}a:focus-visible{outline:3px solid #b48230;outline-offset:4px}code{background:#e8eee0;padding:2px 5px;border-radius:3px}@media(max-width:900px){header,main,footer{padding-left:28px;padding-right:28px}.tool{grid-template-columns:40px 1fr}.tool aside{grid-column:2}nav{gap:12px}}'''
pages={
'index':('AI Tools · Claude 使用小工具','''<p class="eyebrow">AI TOOLS / 本地预览</p><h1>连接不通、记录难找，<br>先把问题查清楚。</h1><p class="lead">三个小工具，分别查看账号验证状态、检查网络连接、寻找本地对话。按你遇到的问题选择。</p><a class="button" href="download.html">下载预览版</a><a class="button alt" href="privacy.html">数据会去哪里</a><p class="note">支持构建 macOS 与 Windows 版本。完整实机、真实账号验证及代码签名尚未完成。</p><div class="tools"><article class="tool"><span class="num">01</span><div><h2><a href="kyc.html">KYC 状态查询</a></h2><p>登录 Claude，点击扩展，查看各组织的验证状态。查询失败会单独说明原因。</p></div><aside>Chrome 扩展<br>当前标签页 · 主动检查</aside></article><article class="tool"><span class="num">02</span><div><h2><a href="network.html">网络诊断</a></h2><p>浏览器看出口；本地程序核对配置与连接阶段，区分直连和代理。</p></div><aside>Chrome 扩展 + 本地程序<br>macOS / Windows</aside></article><article class="tool"><span class="num">03</span><div><h2><a href="sessions.html">会话记录查找</a></h2><p>记得聊过，却找不到了？按项目、日期和关键词寻找磁盘中已有记录。</p></div><aside>本地程序<br>只读检索 · Markdown 导出</aside></article></div>'''),
'kyc':('KYC 状态查询 · AI Tools','''<p class="eyebrow">01 / CHROME 扩展</p><h1>当前账号，<br>需要做 KYC 吗？</h1><p class="lead">在已登录的 Claude 页面点击检查，按组织展示接口返回的验证状态。组织名称与标识默认折叠。</p><a class="button" href="download.html">获取扩展</a><div class="sample"><small>界面示意，以下不是实际账号结果</small><pre>组织 1    无需验证
组织 2    审核中
组织 3    查询失败：HTTP 403

[ 复制脱敏结果 ]</pre></div><h2>怎么用</h2><ol><li>下载扩展 ZIP 并解压，在 Chrome 扩展管理页开启开发者模式，选择“加载已解压的扩展程序”。这一步仅用于试用。</li><li>打开已登录的 claude.ai 页面，从工具栏打开 AI Tools。</li><li>点击“检查当前账号”，查看结果。需要反馈时，使用“复制脱敏结果”。</li></ol><h2>状态与错误要分开看</h2><p>HTTP 403 是查询请求被拒，不等于 KYC 审核被拒。接口返回未知状态时保留原值；脱敏分享仅标记为未知状态，避免分享意外字段。</p><p class="note">真实账号接口尚未验收。此工具不提交验证材料，不处理审核，也不能判断账号是否会被封。</p>'''),
'network':('网络诊断 · AI Tools','''<p class="eyebrow">02 / 浏览器与本机</p><h1>同一台电脑，<br>也可能走不同的网络。</h1><p class="lead">浏览器能打开，不代表 Claude Code 的代理配置相同。分别检查两条路径，保留每次请求的证据。</p><a class="button" href="download.html">下载检测工具</a><h2>只看浏览器：使用扩展</h2><p>查看访问 ipify 时观测到的 IPv4、IPv6，以及浏览器语言、时区。WebRTC 单独开启，每次确认后才联系 Google STUN 服务。</p><h2>排查 Claude Code：运行本地程序</h2><ol><li>按系统下载本地程序，启动后在浏览器操作。程序只监听本机。</li><li>填入项目目录，先检查配置来源。需要测试连通性时勾选网络请求。</li><li>展开测试结果，查看 DNS、连接、TLS 和 HTTP 阶段。可以导出脱敏报告。</li></ol><div class="sample"><small>报告固定分区</small><pre>检测器环境      本程序读取到的环境变量
配置证据        用户、项目、本机项目与固定策略文件
测试请求结果    直连 / 代理，各阶段响应
运行中的 Claude 未检测</pre></div><p>本版支持不带认证的 HTTP/HTTPS 代理测试。SOCKS、带密码的代理和自定义 CA 会明确标注限制，不会偷偷改用直连。</p><p class="note">此结果只说明连接情况，不判断账号状态。网络服务会看到测试请求的出口 IP；配置和聊天不上传。</p>'''),
'sessions':('会话记录查找 · AI Tools','''<p class="eyebrow">03 / 本地记录</p><h1>找回对话里的那句话。</h1><p class="lead">按项目、日期与关键词检索已有 JSONL 记录，先预览，再导出 Markdown。工具不会修改源文件。</p><a class="button" href="download.html">下载本地程序</a><h2>从一段关键词开始</h2><ol><li>切换到“会话记录”，使用默认 Claude 记录目录，或添加你明确选择的备份目录。</li><li>点击扫描，再按项目、UTC 日期或关键词缩小范围。多个关键词按全部包含匹配。</li><li>点开记录查看文字。子任务默认折叠，工具调用、图片与思考块不会展示正文。</li><li>导出 Markdown 后自行保存。导出文件包含对话原文，分享前请检查内容。</li></ol><div class="sample"><small>示例关键词</small><pre>代理 配置
数据库 迁移
上周讨论的项目名称</pre></div><p>单次最多扫描 5000 个文件、128 MiB、60 秒；超出范围会提示部分完成。坏行不会阻止其他记录显示，无法识别的格式会注明。</p><p class="note">只能找到磁盘中仍存在的记录。已删除、没有备份的数据不能靠本工具恢复。</p>'''),
'download':('下载预览版 · AI Tools','''<p class="eyebrow">DOWNLOAD / 0.1.0 PREVIEW</p><h1>选择你的系统。</h1><p class="lead">扩展负责浏览器检查；本地程序包含网络诊断和会话查找。源代码与说明在同一项目目录中。</p><p class="note">这是未签名的开发预览版，完整实机及真实 KYC 账号验收未完成。启动步骤见下方；本工具不会修改系统的全局安全设置。</p><!-- downloads:start --><p>请先运行 scripts/build.sh 生成下载文件。</p><!-- downloads:end --><h2>启动方式</h2><p>Windows 下载后运行 .exe。macOS 下载对应架构的 ZIP，解压后双击 AI Tools.command。终端会显示本机地址，并自动打开浏览器；标签页关掉后，可从终端复制地址重开。点击页面右上角“退出程序”或在终端按 Ctrl+C 结束。macOS 包尚未签名公证；如果系统提示身份不明，确认来源与校验值后，可由你本人在“系统设置 → 隐私与安全性 → 仍要打开”中决定是否允许此程序。不要关闭全局安全保护。</p><p>只想采集终端配置，可运行 <code>aitools net --offline --json</code>。程序位于当前目录时命令前加 <code>./</code>，Windows 使用实际 .exe 文件名。</p><h2>安装扩展</h2><p>解压扩展 ZIP，在 Chrome 的扩展管理页开启开发者模式，再选择“加载已解压的扩展程序”，指向解压后的 extension 目录。尚未上架 Chrome 商店。</p><h2>更新记录</h2><p>0.1.0 预览版：KYC 状态展示、浏览器出口检查、主动 WebRTC 检测、本地配置诊断与会话检索。</p>'''),
'privacy':('数据说明 · AI Tools','''<p class="eyebrow">PRIVACY / 数据说明</p><h1>哪些留在本机，<br>哪些请求会发出去。</h1><h2>KYC 查询</h2><p>你主动点击后，扩展在当前 Claude 标签页发起同源查询，使用页面已有登录状态。扩展不读取或导出 Cookie，不向工具网站发送结果，不持久保存账号信息。</p><h2>浏览器与网络测试</h2><p>浏览器出口检测会联系 api.ipify.org 和 api6.ipify.org。确认 WebRTC 检测后，会联系 Google 的 stun.l.google.com:19302。对方会看到相应请求的网络地址。</p><p>本地网络测试在勾选后访问 ipify、api.anthropic.com 和 claude.ai。不带 Cookie、密钥或提示词。离线配置检查不发网络请求。</p><h2>本机配置与对话</h2><p>本地服务只监听 127.0.0.1，API 使用启动时的随机令牌。配置与记录在本机内存处理，不上传。请勿把带令牌的启动地址分享给别人。</p><p>配置报告隐藏密钥、代理认证与 URL 参数；会话 Markdown 导出包含原始文字和来源信息，分享前需要自行检查。关闭程序即清除内存索引。</p><h2>网站</h2><p>这六个静态页面不收集账号、配置、聊天或访问统计，不加载外部脚本、字体与图片。本轮只提供本地预览，没有公网部署。</p>''')}
for name,(title,body) in pages.items():
 content=f'''<!doctype html><html lang="zh-CN"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>{html.escape(title)}</title><style>{CSS}</style></head><body><header><a class="brand" href="index.html">AI Tools<span>Claude 使用小工具</span></a><nav aria-label="导航"><a href="index.html">工具</a><a href="download.html">下载</a><a href="privacy.html">数据说明</a></nav></header><main>{body}</main><footer><span>AI Tools · 开发预览版</span><a href="privacy.html">数据说明</a></footer></body></html>'''
 (ROOT/'site'/f'{name}.html').write_text(content)
print('Generated 6 static pages')
